interface ReleaseGateTestShard {
  index: number;
  count: number;
}

const releaseGateTestShard = parseReleaseGateTestShard(process.env.RELEASE_GATE_TEST_SHARD);
let releaseGateTestOrdinal = 0;

function parseReleaseGateTestShard(raw: string | undefined): ReleaseGateTestShard | undefined {
  if (!raw) return undefined;
  const match = /^([1-9]\d*)\/([1-9]\d*)$/.exec(raw);
  if (!match) {
    throw new Error(`RELEASE_GATE_TEST_SHARD must use <index>/<count>; got ${raw}`);
  }
  const index = Number(match[1]);
  const count = Number(match[2]);
  if (index > count) {
    throw new Error(`RELEASE_GATE_TEST_SHARD index must be <= count; got ${raw}`);
  }
  return { index, count };
}

function shouldRunReleaseGateTest(): boolean {
  const ordinal = releaseGateTestOrdinal;
  releaseGateTestOrdinal += 1;
  if (!releaseGateTestShard) return true;
  return ordinal % releaseGateTestShard.count === releaseGateTestShard.index - 1;
}

function releaseGateIt(...args: Parameters<typeof vitestIt>): ReturnType<typeof vitestIt> {
  const target = shouldRunReleaseGateTest() ? vitestIt : vitestIt.skip;
  return target(...args);
}

type ReleaseGateEachRunner = (
  name: string | Function,
  fn: (...args: any[]) => unknown,
  options?: Parameters<typeof vitestIt>[2],
) => void;

function releaseGateItEach(cases: Parameters<typeof vitestIt.each>[0]): ReleaseGateEachRunner {
  return (name, fn, options): void => {
    for (const testCase of cases as unknown as readonly unknown[]) {
      const target = shouldRunReleaseGateTest() ? vitestIt : vitestIt.skip;
      const each = target.each([
        testCase,
      ] as unknown as Parameters<typeof vitestIt.each>[0]) as unknown as ReleaseGateEachRunner;
      each(name, fn, options);
    }
  };
}

const it = Object.assign(releaseGateIt, vitestIt, {
  each: releaseGateItEach,
}) as typeof vitestIt;

const FRESH_CHECKPOINT_ERGO_NODE_URL = 'http://localhost:9052';
const FRESH_CHECKPOINT_SIDECHAIN_RPC_URL = 'http://localhost:9945';

const checklist = (rows: string, decisionRows = releaseDecisionTable(rows.split('\n').filter(Boolean))): string => `
# Institutional Release Checklist

## Pending Evidence Register

| Gate | Pending evidence or blocker | Status | Publication effect | Required resolution |
|---|---|---|---|---|
${rows}

## Release Decision

| Field | Value |
|---|---|
${decisionRows}

Executable local guard:
`;

function fullChecklist(overrides: string[] = []): string {
  const byItem = new Map(
    REQUIRED_PENDING_EVIDENCE_ROWS.map(row => [row.item, checkedRow(row)]),
  );

  for (const row of overrides) {
    const cells = row.slice(1, -1).split('|').map(cell => cell.trim());
    byItem.set(cells[1], row);
  }

  const rows = [...byItem.values()];
  return checklist(rows.join('\n'), releaseDecisionTable(rows));
}

function checkedRow(row: typeof REQUIRED_PENDING_EVIDENCE_ROWS[number]): string {
  const cleanCheckoutEvidence = row.item === 'Green CI on the final branch'
    ? ` ${completedProductionCandidateCleanCheckoutEvidence}`
    : '';
  const liveRehearsalEvidence = row.item === 'Fresh Ergo testnet lifecycle run'
    ? ` ${completedTestnetLifecycleGateEvidence}`
    : '';
  const localLiveRehearsalEvidence = row.item === 'Fresh local devnet lifecycle run'
    ? ` ${completedLocalLifecycleGateEvidence}`
    : '';
  const recoveryObserveEvidence = recoveryObserveGateEvidenceForItem(row.item);
  const backupRestoreEvidence = backupRestoreGateEvidenceForItem(row.item);
  const technicalAddendumEvidence = technicalAddendumGateEvidenceForItem(row.item);
  const dependencyReviewEvidence = row.item === 'Signer dependency conformance or fail-closed release decision'
    ? ` ${completedProductionCandidateDependencyReviewEvidence}`
    : '';
  const securityReviewEvidence = row.item === 'Independent security review report'
    ? ` ${completedProductionCandidateSecurityReviewEvidence}`
    : '';
  const trustlessBurnEvidence = row.item === 'Trustless burn verification path'
    ? ` ${completedProductionCandidateTrustlessBurnEvidence}`
    : '';
  const benchmarkEvidence = row.item === 'Single, batch, and sharded benchmark evidence'
    ? ` ${completedProductionCandidateBenchmarkEvidence}`
    : '';
  const committeeGovernanceEvidence = row.item === 'Committee governance and key-rotation drill'
    ? ` ${completedProductionCandidateGovernanceEvidence}`
    : '';
  const operatorReadinessEvidence = row.item === 'Operator readiness evidence'
    ? ` ${completedProductionCandidateOperatorReadinessEvidence}`
    : '';
  const externalIntegrationEvidence = row.item === 'External integration package review'
    ? ` ${completedProductionCandidateExternalIntegrationEvidence}`
    : '';

  return (
    `| ${row.gate} | ${row.item} | Checked | Publication blocker for public release | ` +
    `Completed evidence covers ${row.requiredResolutionTerms.join(', ')}. ` +
    `Evidence: artifact://release-gate/${slug(row.item)}.log${cleanCheckoutEvidence}${localLiveRehearsalEvidence}${liveRehearsalEvidence}${recoveryObserveEvidence}${backupRestoreEvidence}${technicalAddendumEvidence}${dependencyReviewEvidence}${securityReviewEvidence}${trustlessBurnEvidence}${benchmarkEvidence}${committeeGovernanceEvidence}${operatorReadinessEvidence}${externalIntegrationEvidence} |`
  );
}

function checkedFreshTestnetLifecycleRowWithoutValidatedLiveEvidence(): string {
  const row = REQUIRED_PENDING_EVIDENCE_ROWS.find(
    candidate => candidate.item === 'Fresh Ergo testnet lifecycle run',
  );
  if (!row) throw new Error('Unknown required evidence row: Fresh Ergo testnet lifecycle run');

  return (
    `| ${row.gate} | ${row.item} | Checked | Publication blocker for public release | ` +
    `Completed evidence covers ${row.requiredResolutionTerms.join(', ')}. ` +
    `Evidence: artifact://release-gate/${slug(row.item)}.log |`
  );
}

function checkedRowOmitting(item: string, omittedTerms: string[]): string {
  const row = REQUIRED_PENDING_EVIDENCE_ROWS.find(candidate => candidate.item === item);
  if (!row) throw new Error(`Unknown required evidence row: ${item}`);
  const terms = row.requiredResolutionTerms.filter(term => !omittedTerms.includes(term));

  return (
    `| ${row.gate} | ${row.item} | Checked | Publication blocker for public release | ` +
    `Completed evidence covers ${terms.join(', ')}. ` +
    `Evidence: artifact://release-gate/${slug(row.item)}.log |`
  );
}

function isReleaseNoteUpdateTerm(term: string): boolean {
  return /release-note update evidence|release-note updates/i.test(term);
}

function isChecklistUpdateTerm(term: string): boolean {
  return /checklist update evidence|checklist updates/i.test(term);
}

function isDistinctPublicationUpdateTargetTerm(term: string): boolean {
  if (/external review/i.test(term)) return false;
  return (
    /distinct completed/i.test(term) &&
    /update evidence targets/i.test(term) &&
    (/release-note\/checklist/i.test(term) || /checklist\/release-note/i.test(term))
  );
}

function isDistinctLinkedEvidenceTargetTerm(term: string): boolean {
  return /distinct completed evidence targets across linked/i.test(term);
}

function isPublicationUpdateContradictionTerm(term: string): boolean {
  return /internally non-contradictory/i.test(term) && /publication-update/i.test(term);
}

function isReviewerSignoffTerm(term: string): boolean {
  return /\bsign-off\b/i.test(term);
}

function isReviewerDecisionSummaryTerm(term: string): boolean {
  return term.trim().toLowerCase() === 'reviewer decision summary';
}

