function checkedRowWithExtraEvidence(item: string, extraEvidence: string): string {
  const row = REQUIRED_PENDING_EVIDENCE_ROWS.find(candidate => candidate.item === item);
  if (!row) throw new Error(`Unknown required evidence row: ${item}`);

  return checkedRow(row).replace(/\s\|$/, ` ${extraEvidence} |`);
}

const TESTNET_LIFECYCLE_SUBMITTED_TX_ID = 'a'.repeat(64);
const RECOVERY_BURN_TX_ID = 'b'.repeat(64);
const RECOVERY_SINGLETON_ID = 'c'.repeat(64);
const BENCHMARK_LIVE_BATCH_TX_ID = TESTNET_LIFECYCLE_SUBMITTED_TX_ID;
const DRIFTED_BENCHMARK_LIVE_BATCH_TX_ID = 'd'.repeat(64);
const GOVERNANCE_OLD_KEY_HASH = 'e'.repeat(64);
const GOVERNANCE_NEW_KEY_HASH_1 = '1'.repeat(64);
const GOVERNANCE_NEW_KEY_HASH_2 = '2'.repeat(64);
const GOVERNANCE_NEW_KEY_HASH_3 = '3'.repeat(64);
const GOVERNANCE_NON_COMMITTEE_KEY_HASH = '9'.repeat(64);

function overCapBurnTxHashes(): string[] {
  return Array.from({ length: 11 }, (_, index) => (0x10 + index).toString(16).repeat(32));
}

function overCapBridgeEventRootHexes(): string[] {
  return Array.from({ length: 11 }, (_, index) => (0x40 + index).toString(16).repeat(32));
}

function overCapAggregateClaims() {
  return overCapBurnTxHashes().map((burnTxHash, index) => ({
    burnTxHash,
    sidechainBlockHeight: 200 + index,
    sidechainHeaderHashHex: (0x60 + index).toString(16).repeat(32),
    bridgeEventRootHex: (0x80 + index).toString(16).repeat(32),
    ergoAnchorHeight: 100 + index,
  }));
}

