    'Unlock payout binding': '`relayer/src/contract-invariants.test.ts`',
    'DUP duplicate prevention': '`relayer/src/aggregate-settlement-service.test.ts`',
    'Batch settlement all-or-nothing reconciliation': '`relayer/src/aggregate-settlement-service.test.ts`',
    'Unified batch AVL proof': '`wasm-avl/src/lib.rs`',
    'Anchor height determinism': '`relayer/src/aggregate-anchor.test.ts`',
    'Clean checkout reproducibility': '`.github/workflows/relayer-checks.yml`',
    'Technical addendum claim boundary': '`relayer/src/technical-addendum-evidence.test.ts`',
    'Local secret/doxxing hygiene': '`relayer/src/publication-hygiene.test.ts`',
    'Dependency risk register': '`docs/dependency-risk-register.md`',
    'Phantom burn trust minimization': '`docs/aggregate-settlement-threat-model.md`, `relayer/src/trustless-burn-evidence.test.ts`',
