function completedLifecycleEvidenceArtifact(gate: string): string {
  const base = `artifact://release-gate/completed-${slug(gate)}.md completed lifecycle evidence for ${gate}`;
  if (gate === 'Fresh testnet lifecycle') {
    return `${base}; Ergo node network testnet`;
  }
  if (gate === 'Failed broadcast / phantom AVL evidence') {
    return `${base}; failed-broadcast phantom-AVL evidence proves no phantom DUP/AVL history`;
  }
  if (gate === 'Reorged burn / stale singleton evidence') {
    return `${base}; reorged-burn stale-singleton detection and recovery evidence`;
  }
  if (gate === 'Backup-restore or reconstructibility evidence') {
    return `${base}; Backup Restore Evidence Template; npm run backup:validate; backup-restore reconstructibility`;
  }
  return base;
}

