function releaseDecisionTable(rows: string[], overrides: {
  proposedReleaseLevel?: string;
  finalDecision?: string;
  publicReleaseAllowed?: string;
  productionReadyClaimsAllowed?: string;
  testnetProductionCandidateClaimsAllowed?: string;
  unresolvedPublicationBlockers?: string;
  releaseNotesStatus?: string;
  releaseNotesArtifact?: string;
} = {}): string {
  const unresolvedBlockers = rows.filter(isUnresolvedPublicationBlocker);
  const blocked = unresolvedBlockers.length > 0;
  const proposedReleaseLevel = overrides.proposedReleaseLevel ?? (blocked ? 'blocked' : 'institutional reference');
  const releaseNotesStatus = overrides.releaseNotesStatus ?? (blocked ? 'not ready' : 'linked');
  const releaseNotesArtifact = overrides.releaseNotesArtifact ?? (
    releaseNotesStatus === 'linked'
      ? 'artifact://release-notes/completed-release-notes.md; npm run release-notes:validate command output: artifact://release-notes/validation.log PASS exit code 0 no structural issues validated target artifact://release-notes/completed-release-notes.md'
      : 'not linked'
  );

  return [
    ['Proposed release level', proposedReleaseLevel],
    ['Final decision', overrides.finalDecision ?? (blocked ? 'blocked' : 'approved')],
    ['Public release allowed', overrides.publicReleaseAllowed ?? (blocked ? 'no' : 'yes')],
    ['Production-ready claims allowed', overrides.productionReadyClaimsAllowed ?? 'no'],
    [
      'Testnet production-candidate claims allowed',
      overrides.testnetProductionCandidateClaimsAllowed ??
        (proposedReleaseLevel === 'production deployment candidate' && !blocked ? 'yes' : 'no'),
    ],
    ['Unresolved publication blockers', overrides.unresolvedPublicationBlockers ?? String(unresolvedBlockers.length)],
    ['Release notes status', releaseNotesStatus],
    ['Release notes artifact', releaseNotesArtifact],
  ].map(row => `| ${row.join(' | ')} |`).join('\n');
}

function isUnresolvedPublicationBlocker(row: string): boolean {
  const cells = row.slice(1, -1).split('|').map(cell => cell.trim());
  return cells[2] !== 'Checked' && /\bPublication blocker\b/.test(cells[3] ?? '');
}

function unresolvedRequiredRow(item: string, status: 'Pending evidence' | 'Open blocker'): string {
  const row = REQUIRED_PENDING_EVIDENCE_ROWS.find(candidate => candidate.item === item);
  if (!row) throw new Error(`Unknown required evidence row: ${item}`);

  return (
    `| ${row.gate} | ${row.item} | ${status} | Publication blocker for public release | ` +
    `Link completed evidence covering ${row.requiredResolutionTerms.join(', ')}. ` +
    `Evidence target: artifact://release-gate/${slug(row.item)}.log |`
  );
}

function governanceRotationEvidence(step: string): string {
  switch (step) {
    case 'Identify old committee public keys':
      return `old committee public keys hashes only ${GOVERNANCE_OLD_KEY_HASH}`;
    case 'Identify new committee public keys':
      return (
        `new committee public keys hashes only ${GOVERNANCE_NEW_KEY_HASH_1} ` +
        `${GOVERNANCE_NEW_KEY_HASH_2} ${GOVERNANCE_NEW_KEY_HASH_3}`
      );
    case 'Validate threshold policy':
      return 'm/n threshold policy 2/3 quorum and member-loss tolerance validated';
    case 'Simulate member loss or lost-key tolerance':
      return 'member-loss lost-key tolerance drill validated';
    case 'Compile affected contracts':
      return 'npm run contracts:check compile placeholder validation passed';
    case 'Evaluate old and new signer behavior':
      return 'old and new signer behavior compared through signing guard evidence';
    case 'Preserve singleton continuity':
      return 'singleton NFT register script and value continuity verified';
    case 'Reconcile deployment state':
      return 'deployment-state network singleton reconciliation verified';
    case 'Verify rollback plan':
      return 'rollback previous-authority recovery plan verified';
    default:
      return `rotation evidence for ${step}`;
  }
}

function governancePositiveEvidence(check: string): string {
  if (check === 'New committee executes signer-gated mutation after rotation') {
    return (
      `new committee signer-gated mutation accepted by threshold signers ` +
      `${GOVERNANCE_NEW_KEY_HASH_1} ${GOVERNANCE_NEW_KEY_HASH_2}`
    );
  }
  return (
    `member-loss tolerance threshold quorum signer-gated mutation validated by ` +
    `${GOVERNANCE_NEW_KEY_HASH_1} ${GOVERNANCE_NEW_KEY_HASH_3}`
  );
}

function governanceNegativeEvidence(check: string): string {
  switch (check) {
    case 'Old single signer attempts signer-gated mutation after rotation':
      return `old signer signer-gated mutation rejected ${GOVERNANCE_OLD_KEY_HASH}`;
    case 'Non-committee signer attempts signer-gated mutation':
      return `non-committee signer signer-gated mutation rejected ${GOVERNANCE_NON_COMMITTEE_KEY_HASH}`;
    case 'Committee threshold below policy':
      return 'threshold below policy rejected';
    case 'MCU references stale SCS NFT after SCS redeploy':
      return 'MCU stale SCS NFT after redeploy blocked';
    case 'MCL emergency escape path is accidentally committee-gated':
      return 'MCL emergency escape committee-gated path blocked';
    case 'Broadcast is enabled before readiness review':
      return 'broadcast before readiness review blocked';
    case 'Deployment state points to the wrong network':
      return 'deployment-state wrong-network mismatch blocked';
    default:
      return `negative governance evidence for ${check}`;
  }
}

function slug(value: string): string {
  return value.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
}

function trailingToken(value: string): string {
  return value.trim().split(/\s+/).slice(-1)[0] ?? '';
}

function firstArtifactTarget(value: string): string {
  return value.match(/artifact:\/\/[^\s;),]+/)?.[0] ?? '';
}

function withoutArtifactTargets(value: string): string {
  return value.replace(/artifact:\/\/[^\s;),]+/g, '').replace(/\s+/g, ' ').trim();
}
